package com.wms.repository; import com.wms.model.entity.Location; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.data.jpa.repository.Query; import java.util.List; import java.util.Optional; public interface LocationRepository extends JpaRepository<Location,Long> { Optional<Location> findByWarehouseIdAndCode(Long warehouseId,String code); @Query("select l from Location l join fetch l.warehouse where l.warehouse.id = :warehouseId") List<Location> findByWarehouseId(Long warehouseId); @Query("select l from Location l join fetch l.warehouse") List<Location> findAllWithWarehouse(); }
